svg.script:
let games=[];

let category="All";


const gamesURL=

"https://raw.githubusercontent.com/CowGoMoo357/htmlgamesrepos/main/games.json";





async function loadGames(){


try{


let response =
await fetch(gamesURL);



let json =
await response.json();



games=json.games;



render();


}

catch(e){


document
.getElementById("games")
.innerHTML=

"<div class='card'><h2>Unable to load games</h2></div>";


}


}





function render(){


let box =
document.getElementById("games");


box.innerHTML="";



let list=games;



if(category!=="All"){


list =
games.filter(
g=>g.category===category
);


}



list.forEach(game=>{


let card =
document.createElement("div");


card.className="card";



card.innerHTML=

`

<h2>
${game.name}
</h2>

<p>
${game.category}
</p>

<button class="play">
Play
</button>

`;



card
.querySelector(".play")
.onclick=function(){


fetch(game.url)

.then(r=>r.text())

.then(html=>{


let tab =
window.open();


tab.document.open();

tab.document.write(html);

tab.document.close();


});


};



box.appendChild(card);



});


}





document
.querySelectorAll(".category")
.forEach(btn=>{


btn.onclick=function(){


document
.querySelectorAll(".category")
.forEach(x=>
x.classList.remove("active")
);



btn.classList.add("active");


category =
btn.dataset.category;


render();


};


});






document
.getElementById("search")
.oninput=function(){


let q =
this.value.toLowerCase();



let old =
category;


category="All";



let filtered =
games.filter(
g=>
g.name
.toLowerCase()
.includes(q)
);



let box =
document.getElementById("games");


box.innerHTML="";



filtered.forEach(game=>{


let card =
document.createElement("div");


card.className="card";


card.innerHTML=

`

<h2>${game.name}</h2>

<p>${game.category}</p>

<button class="play">
Play
</button>

`;



card.querySelector(".play")
.onclick=()=>{


fetch(game.url)
.then(r=>r.text())
.then(html=>{


let w=window.open();

w.document.write(html);


});


};



box.appendChild(card);


});



};



loadGames();
